const wait = (ms, value, fail = false) =>
  new Promise((resolve, reject) => setTimeout(() => (fail ? reject(new Error(value)) : resolve(value)), ms));

async function loadDashboard() {
  const started = Date.now();
  const [user, orders] = await Promise.all([wait(100, 'Asha'), wait(100, ['o1', 'o2'])]);
  const [recs] = await Promise.allSettled([wait(20, 'recs down', true)]);
  return {
    user,
    orders,
    recommendations: recs.status === 'fulfilled' ? recs.value : [],
    ms: Math.round((Date.now() - started) / 10) * 10
  };
}

loadDashboard().then(console.log);
// { user: 'Asha', orders: [ 'o1', 'o2' ], recommendations: [], ms: 120 } (approximately)

