const make = () => [t(30, 'a'), t(10, 'b-error', true), t(20, 'c')];

Promise.all(make()).then(v => console.log('all', v), e => console.log('all rejected', e));
Promise.allSettled(make()).then(r => console.log('allSettled', r.map(x => x.status).join(',')));
Promise.race(make()).then(v => console.log('race', v), e => console.log('race rejected', e));
Promise.any(make()).then(v => console.log('any', v));

