const lines = stdin.trim().split('\n').map(l => l.trim()).filter(Boolean);
const mode = lines[0];
const tasks = lines.slice(1).map((line, i) => {
  const [name, status, delay, value] = line.split(' ');
  return { name, ok: status === 'ok', delay: Number(delay), value, i };
});

const bySettleTime = [...tasks].sort((a, b) => a.delay - b.delay || a.i - b.i);
const latest = Math.max(...tasks.map(t => t.delay));
const out = [];

if (mode === 'all') {
  const firstFail = bySettleTime.find(t => !t.ok);
  if (firstFail) out.push('rejected: ' + firstFail.value, 'at ' + firstFail.delay + 'ms');
  else out.push('fulfilled: [' + tasks.map(t => t.value).join(',') + ']', 'at ' + latest + 'ms');
} else if (mode === 'allSettled') {
  for (const t of tasks) out.push(t.name + ': ' + (t.ok ? 'fulfilled ' : 'rejected ') + t.value);
  out.push('at ' + latest + 'ms');
} else if (mode === 'race') {
  const first = bySettleTime[0];
  out.push((first.ok ? 'fulfilled: ' : 'rejected: ') + first.value, 'at ' + first.delay + 'ms');
} else if (mode === 'any') {
  const firstOk = bySettleTime.find(t => t.ok);
  if (firstOk) out.push('fulfilled: ' + firstOk.value, 'at ' + firstOk.delay + 'ms');
  else out.push('rejected: AggregateError [' + tasks.map(t => t.value).join(',') + ']', 'at ' + latest + 'ms');
}
console.log(out.join('\n'));
